package com.johnkueh.flare.groceries

import android.app.Application
import com.johnkueh.sync.client.Flags

/** Starts the flags once per process, before any screen: they refresh when
 *  the app comes to the foreground and every few minutes while it's open. */
class GroceriesApp : Application() {
    /** example/flags.json's flags: `flags.banner`, `flags.readOnly`…,
     *  generated by flare-flags.gradle. */
    lateinit var flags: Flags
        private set

    override fun onCreate() {
        super.onCreate()
        flags = Flags.start(this, BuildConfig.SERVER)
    }
}
